import{_ as c,C as A,o,c as p,j as a,a as d,b as r,w as t,E as n,a3 as s,a2 as l}from"./chunks/framework.CZqXuAiL.js";const _=JSON.parse('{"title":"Architecture Overview","description":"GameFilter XDP internals — the aya-eBPF kernel program, userspace loader/CLI, API daemon, OpenShield sync, map layout (TENANTS_MAP, FILTER_MAP, PORT_MAP, ADMIT_MAP, FAIL_MAP, WHITELIST/BLACKLIST, STATS, CONFIG), the packet pipeline, and the admission/ban state machine.","frontmatter":{"title":"Architecture Overview","description":"GameFilter XDP internals — the aya-eBPF kernel program, userspace loader/CLI, API daemon, OpenShield sync, map layout (TENANTS_MAP, FILTER_MAP, PORT_MAP, ADMIT_MAP, FAIL_MAP, WHITELIST/BLACKLIST, STATS, CONFIG), the packet pipeline, and the admission/ban state machine."},"headers":[],"relativePath":"gamefilter-xdp/architecture/overview.md","filePath":"gamefilter-xdp/architecture/overview.md","lastUpdated":1787468851000}'),m={name:"gamefilter-xdp/architecture/overview.md"};function h(P,e,u,E,f,S){const i=A("Mermaid");return o(),p("div",null,[e[3]||(e[3]=a("h1",{id:"architecture-overview",tabindex:"-1"},[d("Architecture Overview "),a("a",{class:"header-anchor",href:"#architecture-overview","aria-label":'Permalink to "Architecture Overview"'},"​")],-1)),e[4]||(e[4]=a("p",null,"GameFilter XDP is two programs and a shared-types crate, all Rust:",-1)),(o(),r(s,null,{default:t(()=>[n(i,{id:"mermaid-6",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20subgraph%20Kernel%0A%20%20%20%20%20%20%20%20XDP%5Bgamefilter-ebpf%3Cbr%2F%3EXDP%20program%3Cbr%2F%3Eaya-ebpf%2C%20no_std%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Userspace%0A%20%20%20%20%20%20%20%20CLI%5Bgamefilter%20CLI%20%2F%20loader%3Cbr%2F%3Eaya%5D%0A%20%20%20%20%20%20%20%20D%5Bgamefilter%20daemon%3Cbr%2F%3Eaxum%20HTTP%20API%5D%0A%20%20%20%20%20%20%20%20S%5BOpenShield%20sync%20task%3Cbr%2F%3Ereqwest%5D%0A%20%20%20%20end%0A%20%20%20%20OS%5BOpenShield-XDP%3Cbr%2F%3Eapi%20%2F%20file%20%2F%20pinned%20maps%5D%0A%20%20%20%20MAPS%5B(Pinned%20maps%3Cbr%2F%3E%2Fsys%2Ffs%2Fbpf%2Fgamefilter)%5D%0A%0A%20%20%20%20XDP%20%3C--%3E%20MAPS%0A%20%20%20%20CLI%20%3C--%3E%20MAPS%0A%20%20%20%20D%20%3C--%3E%20MAPS%0A%20%20%20%20S%20--%3E%20MAPS%0A%20%20%20%20OS%20--%3E%20S%0A%20%20%20%20D%20---%20S%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=l('<ul><li><strong>eBPF kernel program</strong> (<code>gamefilter-ebpf/</code>) — a single <code>#[xdp]</code> entry point written with aya-ebpf (<code>no_std</code>, <code>no_main</code>). Parses IPv4/IPv6 + TCP/UDP, runs destination IP checks (<code>TENANTS_MAP</code> in dedicated mode), whitelist/blacklist, port ownership, admission, and validators. Non-IP or unparseable traffic is passed — fail-open by design.</li><li><strong>Userspace loader + CLI</strong> (<code>gamefilter/</code>, aya) — loads the object, populates the maps, attaches native-first with generic fallback, pins the link and every map, and exits. All CLI commands (<code>status</code>, <code>whitelist</code>, …) reopen the pinned maps, so they work without any resident process.</li><li><strong>API daemon</strong> (<code>gamefilter daemon</code>, axum) — the management plane: token-authenticated, per-IP rate-limited REST API, 1s rate sampler, live tenant enrollment, plus the OpenShield sync task.</li><li><strong>OpenShield sync</strong> (<code>sync.rs</code>) — polls OpenShield&#39;s lists (API, JSON file, or direct pinned-map read) and diffs them into the kernel maps; local CLI/API entries are marker-tagged and never touched.</li><li><strong>Shared types</strong> (<code>gamefilter-common/</code>) — <code>repr(C)</code> structs that are the kernel ABI (<code>FilterRule</code>, <code>AdmitKey</code>, <code>GlobalConfig</code>, <code>RuleStats</code>, …), compiled into both sides.</li></ul><nav class="table-of-contents"><ul><li><a href="#map-layout">Map layout</a></li><li><a href="#packet-pipeline">Packet pipeline</a></li><li><a href="#admission-and-ban-state-machine">Admission and Ban State Machine</a></li><li><a href="#hot-reload-mechanics">Hot Reload Mechanics</a></li></ul></nav><hr><h2 id="map-layout" tabindex="-1">Map layout <a class="header-anchor" href="#map-layout" aria-label="Permalink to &quot;Map layout&quot;">​</a></h2><p>All maps are pinned under <code>/sys/fs/bpf/gamefilter/maps/</code> at load; the attach itself is pinned as <code>/sys/fs/bpf/gamefilter/link</code> (an fd link — removing the pin detaches the program).</p><table tabindex="0"><thead><tr><th>Map</th><th>Type</th><th>Key → Value</th><th>Notes</th></tr></thead><tbody><tr><td><code>TENANTS_MAP</code></td><td>HASH (65536)</td><td><code>dst_ip[16]</code> → <code>u64</code></td><td>In <code>mode: dedicated</code>, destination IPs not in this map bypass filtering with <code>XDP_PASS</code></td></tr><tr><td><code>FILTER_MAP</code></td><td>ARRAY (64)</td><td>slot → <code>FilterRule</code></td><td>The rule table; position = slot used in stats</td></tr><tr><td><code>PORT_MAP</code></td><td>ARRAY (131072)</td><td><code>proto_idx &lt;&lt; 16 | port</code> → <code>u16</code></td><td><code>proto_idx</code> 0 = TCP, 1 = UDP. Stores <strong>rule_idx + 1</strong> — 0 (zero-init) means &quot;port not owned&quot;</td></tr><tr><td><code>ADMIT_MAP</code></td><td>LRU_HASH (65536)</td><td><code>AdmitKey{src[16], dst[16], rule}</code> → <code>{admit_until_ns}</code></td><td>Sliding admission deadline (monotonic ns). Also written with <code>rule = 0xFFFF</code> as an any-rule marker for fragments</td></tr><tr><td><code>FAIL_MAP</code></td><td>LRU_HASH (65536)</td><td><code>AdmitKey</code> → <code>{window_start_ns, count}</code></td><td>Validation failures inside a 60-second window</td></tr><tr><td><code>WHITELIST</code></td><td>HASH (65536)</td><td><code>addr[16]</code> → <code>u64</code></td><td>Checked first — full bypass. Value 1 = local, 2 = synced</td></tr><tr><td><code>BLACKLIST</code></td><td>HASH (65536)</td><td><code>addr[16]</code> → <code>u64</code></td><td>Value 0 = permanent; otherwise monotonic-ns expiry (temp-bans)</td></tr><tr><td><code>STATS</code></td><td>PERCPU_ARRAY (65)</td><td>slot → <code>RuleStats</code></td><td>One slot per rule; slot 64 is the global entry. Userspace sums across CPUs</td></tr><tr><td><code>CONFIG</code></td><td>ARRAY (1)</td><td>0 → <code>{default_drop, enabled, mode}</code></td><td>Global switches, rewritten on every reload</td></tr></tbody></table><p>Key conventions:</p><ul><li><strong>IP keys are <code>[u8; 16]</code></strong> — IPv4 in the first 4 bytes (rest zero), full IPv6 otherwise.</li><li><strong>Admission is per <code>(source, destination, rule)</code></strong> — being admitted for one tenant VPS does not grant access to another tenant VPS.</li><li>LRU for <code>ADMIT_MAP</code>/<code>FAIL_MAP</code> means flood churn evicts entries instead of failing inserts; the whitelist/blacklist/tenants are plain HASH so entries are never evicted.</li><li>The validator reads payload at fixed offsets with direct packet access; the dynamic-offset read (MC Java next-state byte) goes through <code>bpf_xdp_load_bytes</code>, which validates at runtime.</li></ul><h2 id="packet-pipeline" tabindex="-1">Packet pipeline <a class="header-anchor" href="#packet-pipeline" aria-label="Permalink to &quot;Packet pipeline&quot;">​</a></h2>',9)),(o(),r(s,null,{default:t(()=>[n(i,{id:"mermaid-218",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5BPacket%20arrives%5D%20--%3E%20EN%7Benabled%3F%7D%0A%20%20%20%20EN%20--%20no%20--%3E%20PASS%5BXDP_PASS%5D%0A%20%20%20%20EN%20--%20yes%20--%3E%20PARSE%7BParse%20IPv4%2FIPv6%3Cbr%2F%3E%2B%20TCP%2FUDP%7D%0A%20%20%20%20PARSE%20--%20non-IP%20%2F%20unparseable%20--%3E%20PASS%0A%20%20%20%20PARSE%20--%20ok%20--%3E%20DEDICATED%7Bmode%3A%20dedicated%3F%7D%0A%20%20%20%20DEDICATED%20--%20yes%20--%3E%20TENANT%7Bdst_ip%20in%3Cbr%2F%3ETENANTS_MAP%3F%7D%0A%20%20%20%20TENANT%20--%20no%20(un-enrolled)%20--%3E%20PASS%0A%20%20%20%20TENANT%20--%20yes%20--%3E%20WL%0A%20%20%20%20DEDICATED%20--%20no%20(vps%20mode)%20--%3E%20WL%0A%20%20%20%20WL%7BWHITELIST%3F%7D%20--%20yes%20--%3E%20PASS%0A%20%20%20%20WL%20--%20no%20--%3E%20BL%7BBLACKLIST%3F%3Cbr%2F%3E0%20%3D%20permanent%2C%3Cbr%2F%3Eelse%20expiry%20%3E%20now%7D%0A%20%20%20%20BL%20--%20yes%20--%3E%20DROP%5BXDP_DROP%5D%0A%20%20%20%20BL%20--%20no%20--%3E%20FRAG%7BNon-first%3Cbr%2F%3Efragment%3F%7D%0A%20%20%20%20FRAG%20--%20yes%20--%3E%20FA%7BAny-rule%20admission%3Cbr%2F%3Emarker%20live%3F%7D%0A%20%20%20%20FA%20--%20yes%20--%3E%20PASS%0A%20%20%20%20FA%20--%20no%20--%3E%20DROP%0A%20%20%20%20FRAG%20--%20no%20--%3E%20OWN%7BPORT_MAP%3Cbr%2F%3Eowned%3F%7D%0A%20%20%20%20OWN%20--%20no%20--%3E%20DEF%7Bdefault_drop%3F%7D%0A%20%20%20%20DEF%20--%20yes%20--%3E%20DROP%0A%20%20%20%20DEF%20--%20no%20--%3E%20PASS%0A%20%20%20%20OWN%20--%20yes%20--%3E%20ADM%7BADMIT_MAP%20live%3Cbr%2F%3Efor%20(src%2C%20dst%2C%20rule)%3F%7D%0A%20%20%20%20ADM%20--%20yes%20--%3E%20REFRESH%5BRefresh%20sliding%20TTL%3Cbr%2F%3EXDP_PASS%5D%0A%20%20%20%20ADM%20--%20no%20--%3E%20TCP_NO_PAYLOAD%7BTCP%20with%200%20payload%3Cbr%2F%3ESYN%2FACK%20handshake%3F%7D%0A%20%20%20%20TCP_NO_PAYLOAD%20--%20yes%20--%3E%20PASS_NO_ADMIT%5BXDP_PASS%3Cbr%2F%3Eno%20admission%20granted%5D%0A%20%20%20%20TCP_NO_PAYLOAD%20--%20no%20--%3E%20VAL%7BProtocol%20validator%3Cbr%2F%3Esize%20bounds%20%2B%20magic%20bytes%7D%0A%20%20%20%20VAL%20--%20valid%20--%3E%20ADMIT%5BInsert%20ADMIT_MAP%3Cbr%2F%3EXDP_PASS%5D%0A%20%20%20%20VAL%20--%20invalid%20--%3E%20FAIL%5BIncrement%20FAIL_MAP%3Cbr%2F%3Efailures%20%3E%3D%20max%3F%20-%3E%20BLACKLIST%3Cbr%2F%3EXDP_DROP%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[d(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=a("h2",{id:"admission-and-ban-state-machine",tabindex:"-1"},[d("Admission and Ban State Machine "),a("a",{class:"header-anchor",href:"#admission-and-ban-state-machine","aria-label":'Permalink to "Admission and Ban State Machine"'},"​")],-1)),(o(),r(s,null,{default:t(()=>[n(i,{id:"mermaid-222",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20NewSource%3A%20packet%20arrives%20on%20filter-owned%20port%0A%20%20%20%20NewSource%20--%3E%20Admitted%3A%20packet%20matches%20validator%20(magic%20%2B%20framing)%0A%20%20%20%20NewSource%20--%3E%20Failed%3A%20packet%20fails%20validator%20or%20size%20bounds%0A%20%20%20%20NewSource%20--%3E%20PassedNoAdmit%3A%20TCP%20handshake%20packet%20(payload_len%20%3D%3D%200)%0A%0A%20%20%20%20PassedNoAdmit%20--%3E%20NewSource%3A%20next%20packet%20with%20data%20arrives%0A%0A%20%20%20%20Admitted%20--%3E%20Admitted%3A%20subsequent%20packet%20within%20admission_ttl_sec%20(TTL%20refreshed)%0A%20%20%20%20Admitted%20--%3E%20NewSource%3A%20idle%20%3E%20admission_ttl_sec%20(entry%20evicted%20%2F%20expired)%0A%0A%20%20%20%20Failed%20--%3E%20Failed%3A%20another%20invalid%20packet%20(failure%20count%20increments)%0A%20%20%20%20Failed%20--%3E%20TempBanned%3A%20failures%20%3E%3D%20max_failures%20inside%2060s%20window%0A%20%20%20%20Failed%20--%3E%20NewSource%3A%2060s%20window%20expires%20without%20crossing%20threshold%0A%0A%20%20%20%20TempBanned%20--%3E%20NewSource%3A%20ban_sec%20expires%0A%20%20%20%20TempBanned%20--%3E%20TempBanned%3A%20any%20packet%20while%20banned%20(dropped%20in%20prefilter)%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[d(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=l('<h2 id="hot-reload-mechanics" tabindex="-1">Hot Reload Mechanics <a class="header-anchor" href="#hot-reload-mechanics" aria-label="Permalink to &quot;Hot Reload Mechanics&quot;">​</a></h2><p><code>gamefilter reload</code> and <code>POST /api/v1/config</code> (or <code>/api/v1/reload</code>) apply updates <strong>incrementally without a traffic blip</strong>:</p><ol><li><strong><code>CONFIG</code> map</strong> — updated in place with <code>default_drop</code>, <code>enabled</code>, and <code>mode</code>.</li><li><strong><code>FILTER_MAP</code></strong> — slots updated in place; trailing slots zeroed.</li><li><strong><code>PORT_MAP</code></strong> — computed diff between old rules and new rules: new port bindings are added, and only removed port bindings are reset to <code>0</code>. Unaffected ports are never swept.</li><li><strong><code>TENANTS_MAP</code></strong> — synced with <code>cfg.tenants</code> diff.</li><li><strong><code>ADMIT_MAP</code></strong> — stale admissions are purged <strong>only</strong> for rules whose definition actually changed (ports, validator, or sizes). Unmodified rules preserve their active player admissions.</li></ol>',3))])}const g=c(m,[["render",h]]);export{_ as __pageData,g as default};
